// Pick overdue, unpaid invoices that were not chased in the last 3 days,
// and choose the reminder tier from how many days overdue each one is.
const DAY = 24 * 60 * 60 * 1000;
const now = new Date();
const out = [];
const items = $input.all();
for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const row = item.json;
  const status = String(row['Status'] || '').trim().toUpperCase();
  if (status === 'PAID') continue;
  const due = new Date(row['Due']);
  if (isNaN(due)) continue;
  const daysOverdue = Math.floor((now - due) / DAY);
  if (daysOverdue < 1) continue;
  const last = row['Last chased'] ? new Date(row['Last chased']) : null;
  if (last && !isNaN(last) && (now - last) < 3 * DAY) continue;
  let tier, instruction;
  if (daysOverdue < 15) {
    tier = 'polite';
    instruction = 'Polite first nudge. Friendly, assume it slipped through the cracks.';
  } else if (daysOverdue <= 30) {
    tier = 'firmer';
    instruction = 'Firmer second reminder. Still courteous, but clear the invoice is now well past due and ask for a payment date.';
  } else {
    tier = 'final';
    instruction = 'Final notice. Calm and professional, state that this is the final reminder. Do not add any link; it is added separately.';
  }
  const paymentLink = String(row['Payment link'] || '').trim();
  out.push({ json: { ...row, daysOverdue, tier, instruction,
    paymentLine: tier === 'final' && paymentLink ? `Payment link: ${paymentLink}` : '' }, pairedItem: { item: idx } });
}
return out;
